# Coach illustration placeholders, consciously stylized to avoid representing actual staff.
people = [
 ('mara','#524945','#ad8066','#252323','#342c27','MARA / STRENGTH'),
 ('jalen','#3b4b46','#875f4c','#1f2421','#252d29','JALEN / CONDITIONING'),
 ('eli','#45454d','#a47d64','#322e29','#283439','ELI / COACHING')]
for idx,(name,bg,skin,hair,shirt,label) in enumerate(people,1):
 x=0 if idx==1 else (10 if idx==2 else -15)
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 650 780"><defs><radialGradient id="g" cx=".6" cy=".25" r=".8"><stop stop-color="{bg}"/><stop offset="1" stop-color="#131c1d"/></radialGradient><linearGradient id="face" x1="0" x2="1" y1="0" y2="1"><stop stop-color="{skin}"/><stop offset="1" stop-color="#563b32"/></linearGradient><linearGradient id="torso" x1="0" y1="0" x2="1" y2="1"><stop stop-color="{shirt}"/><stop offset="1" stop-color="#0e1617"/></linearGradient></defs><rect width="650" height="780" fill="url(#g)"/><g opacity=".25" stroke="#81918b"><path d="M70 0v780M170 0v780M270 0v780M370 0v780M470 0v780M570 0v780M0 125h650M0 425h650"/></g><circle cx="370" cy="270" r="230" fill="#9e8d78" opacity=".07"/><g transform="translate({x} 0)"><path d="M70 780c10-214 105-270 256-270S550 565 595 780Z" fill="url(#torso)"/><path d="M265 475h130v90c-34 44-96 47-130 0Z" fill="url(#face)"/><path d="M218 245c-8 12-18 78 0 147 17 69 66 126 116 128 60 2 109-52 123-124 16-74 0-145-10-161l-81-63Z" fill="url(#face)"/><path d="M208 301c-29-85 27-159 120-174 87-14 146 50 136 157-16-16-22-41-32-64-67 19-142-6-194 49l-11 44Z" fill="{hair}"/><path d="M274 354h30M368 354h30" stroke="#3a2c29" stroke-width="8" stroke-linecap="round"/><path d="M331 364l-8 40h19" stroke="#4b322b" stroke-width="5" fill="none"/><path d="M304 448q29 14 58 0" stroke="#51382f" stroke-width="5" fill="none"/><path d="M225 564c52 56 162 70 224 0" fill="none" stroke="#54605b" stroke-width="6" opacity=".6"/><path d="M214 575 173 780M462 580l45 200" stroke="#718077" stroke-width="8" opacity=".18"/></g><rect x="22" y="28" width="126" height="3" fill="#c76a42"/><text x="22" y="51" font-family="Arial,sans-serif" font-size="12" letter-spacing="3" fill="#cbd0c4">DEMO PORTRAIT</text><text x="22" y="738" font-family="Arial,sans-serif" font-size="14" letter-spacing="3" fill="#e4dcd2" opacity=".55">{label}</text></svg>'''
 (p/f'coach-{idx}.svg').write_text(svg)
# Before/after concept art is aligned point-for-point. Illustration, not fabricated client photography.
base='''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 650"><defs><linearGradient id="g"><stop stop-color="BG1"/><stop offset="1" stop-color="BG2"/></linearGradient><radialGradient id="lit"><stop stop-color="#bec8b7" stop-opacity=".26"/><stop offset="1" stop-color="#bec8b7" stop-opacity="0"/></radialGradient></defs><rect width="800" height="650" fill="url(#g)"/><g opacity=".16" stroke="#b0beb2"><path d="M0 80h800M0 170h800M0 260h800M0 350h800M0 440h800M0 530h800M90 0v650M200 0v650M310 0v650M420 0v650M530 0v650M640 0v650M750 0v650"/></g><circle cx="440" cy="280" r="310" fill="url(#lit)"/><path d="M0 580h800" stroke="#94a099" stroke-width="4" opacity=".4"/>
<!-- Athlete: conceptual geometric illustration with measured increments, not an actual person -->
<g transform="translate(0 3)"><ellipse cx="400" cy="220" rx="62" ry="78" fill="SKIN"/><path d="M352 168q48-43 99 1l-16-36q-41-32-71 0Z" fill="#151b1c"/><path d="M330 305q70-51 140 0l30 147-34 118H335l-34-118Z" fill="SHIRT" stroke="EDGECOLOR" stroke-width="4"/><path d="M337 340q-59 15-92 97l25 15 92-77M463 340q59 15 92 97l-25 15-92-77" fill="SKIN" stroke="EDGECOLOR" stroke-width="3"/><path d="M355 560 332 633h45l29-64M449 560l29 73h-45l-29-64" fill="#1d2526" stroke="#56645b" stroke-width="4"/><path d="M340 410h120" stroke="DETAIL" stroke-width="6" opacity=".45"/></g>
<!-- weights, marks and scene -->
<g fill="none" stroke="#bfc5b7" stroke-width="8"><path d="M205 447h390"/></g><g stroke="#1c2222" fill="#273030"><rect x="177" y="403" width="20" height="88" rx="3"/><rect x="199" y="415" width="19" height="65" rx="3"/><rect x="582" y="415" width="19" height="65" rx="3"/><rect x="603" y="403" width="20" height="88" rx="3"/></g><text x="35" y="62" fill="#e1e1d7" font-family="Arial,sans-serif" letter-spacing="4" font-size="12">IRON GYM / CONCEPT STUDY</text><path d="M35 80h180" stroke="ACCENT" stroke-width="3"/><text x="35" y="610" fill="#c8d2c6" font-family="Arial,sans-serif" letter-spacing="3" font-size="10">ILLUSTRATIVE PROGRESS ARTWORK</text></svg>'''
for name,a,b,skin,shirt,edge,detail,accent in [
 ('progress-before.svg','#394341','#1a2424','#9b7868','#6b726d','#4e5a55','#596159','#a4b1a5'),
 ('progress-after.svg','#4d332b','#161e1d','#b58b75','#303b38','#9d6346','#a67250','#c76a42')]:
 svg=base.replace('BG1',a).replace('BG2',b).replace('SKIN',skin).replace('SHIRT',shirt).replace('EDGECOLOR',edge).replace('DETAIL',detail).replace('ACCENT',accent)
 (p/name).write_text(svg)
print('created',len(list(p.glob('*.svg'))),'svg assets')
